  const EXTRA_COLORS = ["#111827", "#6B7280", "#EF4444", "#F97316", "#FACC15", "#22C55E", "#14B8A6", "#3B82F6", "#1E3A8A", "#A855F7", "#EC4899", "#92400E", "#BAE6FD", "#FFFFFF"];
  const near = (a, b) => {
    const p = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
    const [r1, g1, b1] = p(a), [r2, g2, b2] = p(b);
    return Math.hypot(r1 - r2, g1 - g2, b1 - b2) < 48;
  };
  function extraColors(lesson) {
    const base = lesson.palette.map((c) => c.toUpperCase());
    return EXTRA_COLORS.filter((c) => !base.some((b) => near(b, c.toUpperCase())));
  }

